//**************************************************************************************************************************
//FUNÇÕES
//Função que calcula se um número é primo ou não (usaremos uma otimização 6k+1)
bool is_prime(uint64_t n){
//Casos triviais
//0,1
if(n<=1)
return false;

//Casos básicos
if(n==2 || n==3)
return true;
if((n%2)==0 || (n%3)==0)
return false;


//Loop principal
for(uint64_t i=5; i<sqrt(n); i+=6){
if((n%i)==0 || (n%(i+2))==0)
return false;
                            };

//Caso fatores primos não sejam encontrados
return true;

                         };

//Função que testar a conjectura de Goldbach
void goldbach_conjecture(uint64_t n){
//Variáveis locais
uint64_t i, factor1, factor2;
bool test1, test2;
//Procedimentos
//Detectando se o número em questão é par
if((n%2)==1){
printf("O número emq uestão é impar a conjectura de Golbbach não se aplica.\n");
            };
//Loop principal
for(i=2; i<=n/2; ++i){
factor1 = i;
factor2 = (n-factor1);
test1=is_prime(factor1);
