import { writeFileSync } from 'fs';
import { GlobalRegistrator } from '@happy-dom/global-registrator';
import prettier from 'prettier';

GlobalRegistrator.register();

/**
 * @param {unknown} value
 * @returns {value is Function}
 */
const isClass = (value) => {
  return value.toString().startsWith('class');
};

/** @param {Function} klass */
const getClassStaticProperties = (klass) => {
  /** @type {Record<string, unknown>} */
  const extractedProperties = {};
  /** @param {unknown} proto */
  const extract = (proto) => {
    if (proto === null) return;
    if (proto === HTMLElement || proto === HTMLElement.prototype) {
      return;
    }
    Object.getOwnPropertyNames(proto)
      .filter((name) => {
        const isPublic = !name.startsWith('_');
        const isOwn = !['arguments', 'prototype', 'caller', 'constructor', 'name', 'length'].includes(name);
        const isDefined = isOwn && !!proto[name];
        return isPublic && isOwn && isDefined;
      })
      .forEach((name) => {
        extractedProperties[name] = proto[name];
      });
    extract(Object.getPrototypeOf(proto));
  };
  extract(klass);
  return extractedProperties;
};

/** @param {function} klass */
const stubClass = (klass) => {
  const properties = getClassStaticProperties(klass);
  return `class {
    ${Object.entries(properties)
      .map(([key, value]) => {
        let valueString;
        if (typeof value === 'function') {
          valueString = '() => {}';
        } else if (typeof value === 'string') {
          valueString = `\`${value}\``;
        } else if (Array.isArray(value)) {
          valueString = JSON.stringify(value);
        } else if (typeof value === 'object') {
          valueString = JSON.stringify(value);
        } else {
          throw new Error(`Unexpected property type: ${typeof value}`);
        }
        return `static ${key} = ${valueString}`;
      })
      .join('\n')}
  }`;
};

const realExports = await import('./index.js');
const stubbedExports = Object.fromEntries(
  Object.entries(realExports).map(([key, value]) => {
    let newValue;
    if (isClass(value)) {
      newValue = stubClass(value);
    } else if (typeof value === 'function') {
      newValue = '() => {}';
    } else if (typeof value === 'string') {
      newValue = `\`${value}\``;
    } else if (typeof value === 'object') {
      newValue = JSON.stringify(value);
    } else {
      throw new Error(`Unexpected export type: ${typeof value}`);
    }
    return [key, newValue];
  }),
);

const content = Object.entries(stubbedExports)
  .map(([key, value]) => {
    return `export const ${key} = ${value};`;
  })
  .join('\n');

const formatted = await prettier.resolveConfig('./').then(
  /** @param {Record<string, unknown>} options */
  (options) => {
    return prettier.format(content, { ...options, parser: 'babel' });
  },
);

writeFileSync('./index.ssr.js', formatted);

//VAMOS CRIAR UM PROGRAMA QUE IMPLEMENTA A CLASSE DOS NÚMEROS DE FERMAT E O TESTE DE PÉPIN PARA A PRIMALIDADE DOS TESTE DE FERMAT
//COMPILAR ESTE PROGRAMA COM O COMANDO: gcc -o fermat_number fermat_number.c

/*
UM NÚMERO DE FERMAT É UM NÚMERO INTEIRO DA FORMA: F(n)=2^(2^n)+1.

VÁRIAS RELAÇÕES DE RECORRÊNCIA EXISTEM ENVOLVENDO ESTES NÚMEROS, POR EXEMPLO: 
PARA n>1: F(n)=(F(n-1)-1)²+1 E F(n)=F(0).F(1)...F(n-1)+2

O CHAMADO TESTE DE PÉPIN PODE SER USADO PARA DETERMINAR SE UM NÚMERO DE FERMAT É PRIMO OU NÃO.
ESTE TEOREMA BASICAMENTE AFIRMA QUE PARA UM NÚMERO DE FERMAT SER PRIMO ELE TEM DE SATISFAZER A RELAÇÃO: 
3^((F(n)-1)/2)=(F(n)-1) mod(F(n))

PARA MAIORES INFORMAÇÕES: https://en.wikipedia.org/wiki/Pépin%27s_test
                          https://en.wikipedia.org/wiki/Fermat_number

*/

//***************************************************************************************************************************
//CABEÇALHO
#include<stdio.h>
#include<stdbool.h>
#include<stdint.h>
#include"mod_bin_exponentiation.h"
//***************************************************************************************************************************
//FUNÇÕES
//Função que determina se um número inteiro positivo é um número de Fermat
bool is_fermat_number(uint64_t n){
//Variáveis locais
uint64_t i, tester;
//Procedimentos
for(i=0; ; ++i){
tester = bin_pow(2, bin_pow(2, i))+1 ;
if(tester==n)
return true;
if(tester>n)
return false;
               };
                                 };

//Teste de Pépin para testar a primalidade de um número
void pepin_test(uint64_t n){
//Checando se o número em questão é um número de Fermat
bool test1=is_fermat_number(n);

if(test1==false){
printf("O número em questão não é um número de Fermat!\n");
return;
               };

//Teste de primalidade
uint64_t exponent=(n-1)/2;
uint64_t tester=mod_pow(3, exponent, n);

if(tester==(n-1))
printf("O número em questão é primo.\n");
else
printf("O número em questão não é primo.\n");

                           };


