#include "mem/mem.h"
#include "sl_cb.h"


struct sl_callback {
	sl_cb_t* callback;         /* callback function */
	unsigned int fmask;        /* bitmask to match msg_flags */
	struct sl_callback* next;  /* next callback element*/
};

struct sl_callback* slcb_hl[SLCB_LAST];  /* heads of lists (per type) */



void destroy_slcb_lists(void)
{
	struct sl_callback *cbp, *cbp_tmp;
	unsigned int i;

	for( i=0 ; i<SLCB_LAST ; i++) {
		for( cbp=slcb_hl[i]; cbp ; ) {
			cbp_tmp = cbp;
			cbp = cbp->next;
			pkg_free( cbp_tmp );
		}
	}
}


int register_slcb(enum sl_cb_type type, unsigned int fmask, sl_cb_t f)
{
	struct sl_callback *cbp;

	/* build a new callback structure */
	if (!(cbp=pkg_malloc( sizeof( struct sl_callback)))) {
		LM_ERR("out of pkg. mem\n");
		return -1;
	}

	/* fill it up */
	cbp->callback = f;
	cbp->fmask = fmask;
	/* link it at the beginning of the list */
	cbp->next = slcb_hl[type];
	slcb_hl[type] = cbp;

	return 0;
}


void slcb_run_reply_out(struct sip_msg *req, str *buffer,
									union sockaddr_union *dst, int rpl_code)
{
	struct sl_callback *cbp;

	for ( cbp=slcb_hl[SLCB_REPLY_OUT] ; cbp ; cbp=cbp->next ) {
		if (cbp->fmask==0 || cbp->fmask&req->msg_flags) {
			cbp->callback( req, buffer, rpl_code, dst, NULL, 0);
		}
	}
}


void slcb_run_ack_in(struct sip_msg *req)
{
	struct sl_callback *cbp;

	for ( cbp=slcb_hl[SLCB_ACK_IN] ; cbp ; cbp=cbp->next ) {
		if (cbp->fmask==0 || cbp->fmask&req->msg_flags) {
			cbp->callback( req, NULL, 0, NULL, NULL, 0);
		}
	}
}


void slcb_run_req_out(struct sip_msg *req, str *buffer,
			const union sockaddr_union *dst, const struct socket_info *sock, int proto)
{
	struct sl_callback *cbp;

	for ( cbp=slcb_hl[SLCB_REQUEST_OUT] ; cbp ; cbp=cbp->next ) {
		if (cbp->fmask==0 || cbp->fmask&req->msg_flags) {
			cbp->callback( req, buffer, 0, dst, sock, proto);
		}
	}
}

// Remove diacritics from a string
const removeDiacritics = (str) => {
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
};

class Counties {
  _counties = [];

  #setCounties(counties) {
    this._counties = [...this._counties, ...counties];
  }

  #getCounties() {
    return this._counties;
  }

  async getCounties(city) {
    for (const county of this.#getCounties()) {
      if (county.city.toLowerCase() === removeDiacritics(city.toLowerCase())) {
        return county;
      }
    }

    const api_endpoint = `https://api.laurentiumarian.ro/orase/?search=${removeDiacritics(
      city
    )}&page_size=50`;
    const counties_found = [];

    let response = await fetch(api_endpoint).then((response) =>
      response.json()
    );

    while (response.next) {
      counties_found.push(...response.results);
      response = await fetch(response.next).then((response) => response.json());
    }

    counties_found.push(...response.results || []);

    let counties = [];
    counties_found.map((c) => {
      if (c.name.toLowerCase() === removeDiacritics(city.toLowerCase())) {
        counties = [...counties, c.county];
      }
    });

    if (counties.length !== 0) {
      let cityWithountDiacritics = removeDiacritics(city);
      this.#setCounties([{ city: cityWithountDiacritics, county: counties }]);
      return { city: cityWithountDiacritics, county: counties };
    }

    return { city: null, county: null };
  }
}

module.exports = {
  Counties,
};

